{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret afviser forudsætningen i spørgsmålet ved at sige, at det normalt ikke er Udbetaling Danmark, men SU-myndigheden/Styrelsen for Institutioner og Uddannelsesstøtte, der vurderer sagen. Det strider mod de frosne kilder (SU-bek. § 36 og vejledning 3.4.1.3), hvor Udbetaling Danmark er den ansvarlige myndighed. Svaret nævner heller ikke Skattestyrelsen som kilde til arbejdstimer og indkomst. Det angiver ikke, at tidligere arbejde særligt er relevant, når ophøret skyldtes andre forhold og funktionsnedsættelsen ikke er forværret. Det siger heller ikke, at arbejde under studiet indgår. Det nævnte myndighedsskifte er en væsentlig juridisk fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Ingen af de fire kritiske elementer er dækket tydeligt. Skattestyrelsen som kilde til arbejdstimer og indkomst mangler. Ansøgerens egne oplysninger om tidligere arbejdsforhold er kun delvist antydet, uden at det fremgår, at ansøger skal angive dem i ansøgningen. Den særlige relevans af arbejdsophør, der skyldes andre forhold end funktionsnedsættelsen, uden efterfølgende forværring, mangler. Arbejde under studiet nævnes ikke."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret forsøger at besvare, hvilke arbejds- og indkomstoplysninger der indgår i vurderingen, og er ikke fyldt med irrelevant tekst. Indholdet er ufuldstændigt og delvist forkert, men det handler om spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, bekendtgørelse eller vejledningsafsnit."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Svaret citerer ingen kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Svaret citerer ingen kilde, så støtten fra kilden til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at SU-myndigheden/Styrelsen for Institutioner og Uddannelsesstøtte vurderer sagen i stedet for Udbetaling Danmark, hvilket ikke støttes af materialet. Det oplister også oplysninger som honorarer, selvstændig virksomhed, tilpasninger på arbejdspladsen og årsag til jobophør samt en adskillelse fra fribeløbsreglerne, uden at disse har støtte i de frosne kilder."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke den krævede kvalifikation om, at tidligere arbejde især er relevant, når ophøret skyldes andre forhold og funktionsnedsættelsen ikke er forværret. Det siger rigtigt, at indtægt eller tidligere job ikke automatisk afgør sagen, men det er ikke nok."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: oplysningerne indgår i en samlet vurdering, og intet enkeltforhold afgør sagen automatisk. Konklusionen følger af de trin, svaret selv anfører."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Modaliteterne er generelt forsigtige (\"kan blandt andet omfatte\", \"afgør ikke automatisk\") og gør ikke skøn til absolutte regler. Den kategoriske udtalelse om, hvilken myndighed der vurderer, er en indholdsfejl og ikke en modalitetsfejl."
    }
  },
  "xhaile_coverage": {
    "A18": {
      "label": "no",
      "reason": "Svaret nævner ikke, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen. Det nævner arbejdstimer og løn generelt, men uden kilden og uden at Udbetaling Danmark gør det."
    },
    "A19": {
      "label": "partial",
      "reason": "Svaret nævner oplysninger om job, du har haft, men siger ikke, at ansøgerens egne oplysninger om tidligere arbejdsforhold skal angives i ansøgningen og inddrages."
    },
    "A20": {
      "label": "no",
      "reason": "Svaret dækker ikke, at erhvervsarbejde før ansøgningen kan indgå, navnlig når ophøret skyldes andre forhold og der ikke er sket forværring. Det siger heller ikke, at erhvervsarbejde under studiet indgår."
    }
  },
  "overall_notes": "Svaret er forsigtigt formuleret og siger rigtigt, at arbejde og indkomst ikke afgør sagen automatisk. Det peger imidlertid på en forkert myndighed og mangler alle de væsentlige kildebaserede elementer: Skattestyrelsen, ansøgerens egne oplysninger, tidligere arbejde med de særlige forhold og arbejde under studiet. Der er ingen kildehenvisninger."
}

